        case env
        case args
        case requires
        case allow
        case deny
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.id = (try? c.decodeIfPresent(String.self, forKey: .id)) ?? ""
        self.command = (try? c.decodeIfPresent(String.self, forKey: .command)) ?? ""
